import unittest

from kitty import ledger
from kitty.errors import KittyError
from kitty.store import new_state


class MembersTests(unittest.TestCase):
    def setUp(self):
        self.s = new_state("EUR")

    def test_add_and_list(self):
        ledger.add_member(self.s, "Alice")
        ledger.add_member(self.s, "Bob")
        self.assertEqual(ledger.list_members(self.s), ["Alice", "Bob"])

    def test_case_insensitive_duplicate(self):
        ledger.add_member(self.s, "Alice")
        with self.assertRaises(KittyError):
            ledger.add_member(self.s, "alice")

    def test_find_member_canonical(self):
        ledger.add_member(self.s, "Alice")
        self.assertEqual(ledger.find_member(self.s, "ALICE"), "Alice")
        with self.assertRaises(KittyError):
            ledger.find_member(self.s, "Zed")

    def test_accented_name_case_insensitive(self):
        ledger.add_member(self.s, "José")
        self.assertEqual(ledger.find_member(self.s, "JOSÉ"), "José")

    def test_bad_names(self):
        for bad in ["", "  ", "A,B", "A=1"]:
            with self.assertRaises(KittyError, msg=repr(bad)):
                ledger.add_member(self.s, bad)

    def test_remove_unused(self):
        ledger.add_member(self.s, "Alice")
        ledger.add_member(self.s, "Bob")
        ledger.remove_member(self.s, "bob")
        self.assertEqual(self.s["members"], ["Alice"])

    def test_remove_unknown(self):
        with self.assertRaises(KittyError):
            ledger.remove_member(self.s, "Nobody")

    def _expense(self, payer, shares):
        return {"id": "e1", "seq": 1, "date": "2026-01-01", "payer": payer,
                "description": "x", "amount": "10.00", "currency": "EUR",
                "rate": "1", "base_amount": "10.00", "category": "",
                "shares": shares}

    def _payment(self, frm, to):
        return {"seq": 2, "date": "2026-01-01", "from": frm, "to": to,
                "amount": "5.00", "currency": "EUR", "rate": "1",
                "base_amount": "5.00"}

    def test_remove_refused_when_used(self):
        cases = {
            "payer": lambda s: s["expenses"].append(
                self._expense("Bob", {"Alice": "10.00"})),
            "share": lambda s: s["expenses"].append(
                self._expense("Alice", {"Bob": "10.00"})),
            "from": lambda s: s["payments"].append(self._payment("Bob", "Alice")),
            "to": lambda s: s["payments"].append(self._payment("Alice", "Bob")),
        }
        for label, setup in cases.items():
            s = new_state("EUR")
            ledger.add_member(s, "Alice")
            ledger.add_member(s, "Bob")
            setup(s)
            with self.assertRaises(KittyError, msg=label):
                ledger.remove_member(s, "Bob")
            self.assertEqual(s["members"], ["Alice", "Bob"], label)

    def test_set_rate(self):
        ledger.set_rate(self.s, "usd", "0.92")
        self.assertEqual(self.s["rates"], {"USD": "0.92"})
        for cur, rate in [("EUR", "1"), ("USD", "0"), ("USD", "abc")]:
            with self.assertRaises(KittyError, msg=(cur, rate)):
                ledger.set_rate(self.s, cur, rate)
        self.assertEqual(self.s["rates"], {"USD": "0.92"})


if __name__ == "__main__":
    unittest.main()
